create table if not exists public.stories (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, media_path text not null, media_type text not null check (media_type in ('image','video')), caption text not null default '', created_at timestamptz not null default timezone('utc', now()), expires_at timestamptz not null, constraint stories_caption_length check (char_length(caption) <= 300)); create index if not exists stories_active_idx on public.stories(expires_at,created_at); create index if not exists stories_user_created_idx on public.stories(user_id,created_at); alter table public.stories enable row level security; drop policy if exists "Authenticated users can read active stories" on public.stories; create policy "Authenticated users can read active stories" on public.stories for select to authenticated using (expires_at > timezone('utc',now())); drop policy if exists "Users can create their own stories" on public.stories; create policy "Users can create their own stories" on public.stories for insert to authenticated with check (auth.uid()=user_id and expires_at > timezone('utc',now()) and expires_at <= timezone('utc',now())+interval '24 hours'+interval '5 minutes'); drop policy if exists "Users can delete their own stories" on public.stories; create policy "Users can delete their own stories" on public.stories for delete to authenticated using (auth.uid()=user_id); grant select,insert,delete on public.stories to authenticated; revoke all on public.stories from anon; create table if not exists public.story_views (id uuid primary key default gen_random_uuid(),story_id uuid not null references public.stories(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,viewed_at timestamptz not null default timezone('utc',now()),unique(story_id,user_id)); create index if not exists story_views_story_idx on public.story_views(story_id,viewed_at desc); alter table public.story_views enable row level security; drop policy if exists "Users can record story views" on public.story_views; create policy "Users can record story views" on public.story_views for insert to authenticated with check(auth.uid()=user_id); drop policy if exists "Users can read relevant story views" on public.story_views; create policy "Users can read relevant story views" on public.story_views for select to authenticated using(auth.uid()=user_id or exists(select 1 from public.stories s where s.id=story_id and s.user_id=auth.uid())); grant select,insert on public.story_views to authenticated; revoke all on public.story_views from anon; insert into storage.buckets(id,name,public) values('stories','stories',false) on conflict(id) do update set public=false; drop policy if exists "Users can upload story media" on storage.objects; create policy "Users can upload story media" on storage.objects for insert to authenticated with check(bucket_id='stories' and (storage.foldername(name))[1]=auth.uid()::text); drop policy if exists "Authenticated users can read story media" on storage.objects; create policy "Authenticated users can read story media" on storage.objects for select to authenticated using(bucket_id='stories'); drop policy if exists "Users can delete story media" on storage.objects; create policy "Users can delete story media" on storage.objects for delete to authenticated using(bucket_id='stories' and (storage.foldername(name))[1]=auth.uid()::text); notify pgrst,'reload schema';